브라우저면 그게 제일 깔끔함. `requestAnimationFrame`이 다음 프레임 시간 줘서, 그걸로 `dt` 계산하면 됨

```html
<canvas id="game" width="640" height="360"></canvas>

<script>
const canvas = document.getElementById("game");
const ctx = canvas.getContext("2d");

let lastTime = performance.now();

const rect = {
  x: 100,
  y: 100,
  w: 50,
  h: 50,
  vx: 120, // px per second
};

function update(dt) {
  rect.x += rect.vx * dt;

  if (rect.x < 0 || rect.x + rect.w > canvas.width) {
    rect.vx *= -1;
  }
}

function render() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);

  ctx.fillStyle = "tomato";
  ctx.fillRect(rect.x, rect.y, rect.w, rect.h);
}

function loop(now) {
  const dt = (now - lastTime) / 1000;
  lastTime = now;

  update(dt);
  render();

  requestAnimationFrame(loop);
}

requestAnimationFrame(loop);
</script>
```

`dt`가 초 단위라서 속도를 `px per second`로 잡을 수 있음. 프레임 낮아져도 이동량이 대충 맞게 감 ㅇㅇ

그럼 엔진이라기엔 좀 귀여운 생명체인데
---
HTML 캔버스로 가면 바로 보임. 사각형 움직이는 “미니 2D 엔진 껍데기”는 이 정도면 됨.

```html
<!doctype html>
<html>
<head>
  <meta charset="utf-8" />
  <title>tiny 2d engine</title>
  <style>
    body { margin: 0; background: #111; }
    canvas { display: block; margin: 40px auto; background: #222; }
  </style>
</head>
<body>
<canvas id="game" width="640" height="360"></canvas>

<script>
class Engine {
  constructor(canvas) {
    this.canvas = canvas;
    this.ctx = canvas.getContext("2d");
    this.entities = [];
    this.keys = new Set();
    this.lastTime = 0;

    window.addEventListener("keydown", e => this.keys.add(e.key));
    window.addEventListener("keyup", e => this.keys.delete(e.key));
  }

  add(entity) {
    this.entities.push(entity);
  }

  start() {
    requestAnimationFrame(this.loop.bind(this));
  }

  loop(time) {
    const dt = (time - this.lastTime) / 1000;
    this.lastTime = time;

    this.update(dt);
    this.render();

    requestAnimationFrame(this.loop.bind(this));
  }

  update(dt) {
    for (const entity of this.entities) {
      entity.update?.(dt, this);
    }
  }

  render() {
    this.ctx.clearRect(0, 0, this.canvas.width, this.canvas.height);

    for (const entity of this.entities) {
      entity.render?.(this.ctx);
    }
  }
}

class Rect {
  constructor(x, y, w, h, color) {
    this.x = x;
    this.y = y;
    this.w = w;
    this.h = h;
    this.color = color;
    this.speed = 180;
  }

  update(dt, engine) {
    if (engine.keys.has("ArrowLeft")) this.x -= this.speed * dt;
    if (engine.keys.has("ArrowRight")) this.x += this.speed * dt;
    if (engine.keys.has("ArrowUp")) this.y -= this.speed * dt;
    if (engine.keys.has("ArrowDown")) this.y += this.speed * dt;
  }

  render(ctx) {
    ctx.fillStyle = this.color;
    ctx.fillRect(this.x, this.y, this.w, this.h);
  }
}

const canvas = document.getElementById("game");
const engine = new Engine(canvas);

engine.add(new Rect(100, 100, 50, 50, "tomato"));
engine.start();
</script>
</body>
</html>
```

저장해서 브라우저로 열면 방향키로 사각형 움직임.
이제 여기서 충돌 넣으면 “게임엔진이라고 우기기” 가능함.

ㅇㅋ 그럼 핵심만 떼면 이거임

```js
let lastTime = 0;

function loop(currentTime) {
  const dt = (currentTime - lastTime) / 1000;
  lastTime = currentTime;

  update(dt);
  render();

  requestAnimationFrame(loop);
}

requestAnimationFrame(loop);
```

`currentTime`은 브라우저가 넘겨주는 타임스탬프고, `dt`는 지난 프레임 이후 몇 초 지났는지임.  
이거 곱해서 움직이면 프레임 빨라도 안 미친 듯이 질주함.

그럼 엔진이라기보단
---
사각형 이동 런타임임 ㅋㅋ
---
브라우저에서 바로 도는 걸로 하면 이 정도면 됨. `index.html` 하나 만들고 열면 WASD/방향키로 움직임.

```html
<!doctype html>
<html lang="ko">
<head>
  <meta charset="utf-8" />
  <title>Mini 2D Engine</title>
  <style>
    body { margin: 0; background: #111; overflow: hidden; }
    canvas { display: block; }
  </style>
</head>
<body>
<canvas id="game"></canvas>

<script>
const canvas = document.getElementById("game");
const ctx = canvas.getContext("2d");

function resize() {
  canvas.width = window.innerWidth;
  canvas.height = window.innerHeight;
}
window.addEventListener("resize", resize);
resize();

const keys = new Set();

window.addEventListener("keydown", e => keys.add(e.key));
window.addEventListener("keyup", e => keys.delete(e.key));

const player = {
  x: 100,
  y: 100,
  w: 50,
  h: 50,
  speed: 300,
  color: "#7dd3fc"
};

let lastTime = performance.now();

function update(dt) {
  let dx = 0;
  let dy = 0;

  if (keys.has("ArrowLeft") || keys.has("a")) dx -= 1;
  if (keys.has("ArrowRight") || keys.has("d")) dx += 1;
  if (keys.has("ArrowUp") || keys.has("w")) dy -= 1;
  if (keys.has("ArrowDown") || keys.has("s")) dy += 1;

  // 대각선 이동이 더 빨라지는 거 방지
  if (dx !== 0 || dy !== 0) {
    const len = Math.hypot(dx, dy);
    dx /= len;
    dy /= len;
  }

  player.x += dx * player.speed * dt;
  player.y += dy * player.speed * dt;
}

function render() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);

  ctx.fillStyle = player.color;
  ctx.fillRect(player.x, player.y, player.w, player.h);
}

function loop(now) {
  const dt = (now - lastTime) / 1000;
  lastTime = now;

  update(dt);
  render();

  requestAnimationFrame(loop);
}

requestAnimationFrame(loop);
</script>
</body>
</html>
```

이게 일단 게임엔진의 심장만 떼온 거임.  
`loop → update → render` 이 구조만 있어도 “움직이는 무언가”는 만들 수 있음.

ㅇㅋ 그럼 심장만 떼면 이거임

